<?php
require __DIR__.'/bootstrap.php';
use RK\AIVisualizer\Definitions\Registry; use RK\AIVisualizer\Core\Validation; use RK\AIVisualizer\Core\Prompt; use RK\AIVisualizer\Core\Quota; use RK\AIVisualizer\Core\Leads; use RK\AIVisualizer\Core\Engine; use RK\AIVisualizer\Providers\Factory; use RK\AIVisualizer\Frontend\Renderer;
$tests=0;$failed=0;$run=function($name,$fn)use(&$tests,&$failed){$tests++;try{$fn();echo "PASS $name\n";}catch(Throwable $e){$failed++;echo "FAIL $name: ".$e->getMessage()."\n";}};
$definition=Registry::instance()->get('flooring');
$run('flooring definition is registered and options match reference',function()use($definition){t_assert($definition!==null,'definition missing');$fields=$definition->fields();$by=array();foreach($fields as $f)$by[$f['id']]=$f;t_eq(array_keys($by),array('roomType','projectType','preferredStyle','customStyleDescription','woodSpecies','floorDirection','finishPreference','sheen','serviceCity','squareFootage'));t_eq(array_keys($by['roomType']['options']),array('kitchen','living_room','hallway','bedroom','office','retail_gym'));t_eq($by['finishPreference']['options']['rubio_monocoat'],'Rubio Monocoat');});
$run('upload validation accepts JPEG/PNG/WebP sized image and checks dimensions',function()use($definition){$f=tempnam(sys_get_temp_dir(),'rkimg');file_put_contents($f,test_png());$r=new WP_REST_Request();$r->files=array('image'=>array('tmp_name'=>$f,'error'=>0));$u=Validation::upload($r,$definition);t_assert(is_array($u)&&'image/png'===$u['mime'],'valid PNG rejected');file_put_contents($f,test_png(100,100));t_error(Validation::upload($r,$definition),'rk_viz_too_small','small image');file_put_contents($f,'not image');t_error(Validation::upload($r,$definition),'rk_viz_bad_type','invalid type');unlink($f);});
$run('generic field validation rejects invalid option and requires custom description',function()use($definition){$bad=valid_options(array('sheen'=>'shiny'));t_error(Validation::fields($bad,$definition),'rk_viz_bad_options','bad option');$bad=valid_options(array('preferredStyle'=>'custom'));t_error(Validation::fields($bad,$definition),'rk_viz_bad_options','missing custom style');$ok=Validation::fields(valid_options(array('preferredStyle'=>'custom','customStyleDescription'=>'deep walnut')),$definition);t_assert(is_array($ok),'custom input rejected');t_eq($ok['customStyleDescription'],'deep walnut');});
$run('prompt uses definition prompt rules and user selections',function()use($definition){$p=Prompt::build($definition,valid_options(array('woodSpecies'=>'hickory','preferredStyle'=>'gray_weathered','floorDirection'=>'herringbone','sheen'=>'satin','finishPreference'=>'rubio_monocoat')));foreach(array('photorealistic','hickory hardwood','gray, weathered tone','herringbone','satin sheen','hardwax oil','Do not change the walls.') as $needle)t_assert(false!==strpos($p,$needle),'missing prompt fragment: '.$needle);$c=Prompt::build($definition,valid_options(array('preferredStyle'=>'custom','customStyleDescription'=>'deep walnut')));t_assert(false!==strpos($c,'deep walnut'),'custom prompt missing');});
$run('quota consumes and refunds generations while preserving cooldown',function(){ $cfg=array('free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24);$s=array('used'=>0,'bonus_used'=>0,'lead'=>false,'next_at'=>0);t_eq(Quota::status($s,$cfg,100)['freeRemaining'],2);$spent=Quota::consume($s,'free',$cfg,100);t_eq($spent['used'],1);t_eq(Quota::refund($spent,'free',$s)['used'],0);$s['used']=2;t_eq(Quota::status($s,$cfg,100)['phase'],'needs_lead');$s['lead']=true;t_eq(Quota::status($s,$cfg,100)['phase'],'bonus');});
$run('lead validation and deduplicated visualizer association',function(){t_assert(isset(Leads::validate(array('name'=>'','email'=>'bad'))['errors']),'bad lead accepted');$good=Leads::validate(array('name'=>'Pat Smith','email'=>'Pat@Example.com','phone'=>'(309) 555-0100'));t_eq($good['lead']['email'],'pat@example.com');Leads::store($good['lead'],'flooring','gen-one');t_eq(count(Leads::all()),1);t_eq(Leads::all()[0]['visualizer'],'flooring');Leads::store($good['lead'],'flooring','gen-two');t_eq(count(Leads::all()),1);});
$run('mock provider returns normalized successful output and renderer renders all fields',function()use($definition){$f=tempnam(sys_get_temp_dir(),'rkimg');file_put_contents($f,test_png());$provider=Factory::create('mock');$r=$provider->generate(array('image_path'=>$f));t_eq($r['status'],'completed');t_assert(false!==strpos($r['image_url'],'rk-ai-visualizer/'),'result not safely stored');$html=Renderer::shortcode(array('cities'=>"Peoria\nPeoria Heights"));foreach(array('name="roomType"','value="retail_gym"','value="semi_gloss"','value="peoria_heights"','data-viz-lead') as $needle)t_assert(false!==strpos($html,$needle),'renderer missing '.$needle);unlink($f);});
$run('engine mock generation returns result, counts quota, and denies after free uses',function(){update_option('rk_ai_visualizer_settings',array('enabled'=>true,'provider'=>'mock','free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24,'ip_per_hour'=>10));$_COOKIE['rk_ai_viz']=str_repeat('a',32);$f=tempnam(sys_get_temp_dir(),'rkimg');file_put_contents($f,test_png());$e=new Engine();$r=$e->generate('flooring',request_generate($f));t_assert($r instanceof WP_REST_Response,'expected response');t_eq($r->get_data()['status'],'success');t_eq($r->get_headers()['Cache-Control'],'no-store, private');$e->generate('flooring',request_generate($f));$denied=$e->generate('flooring',request_generate($f));t_eq($denied->get_status(),429);t_eq($denied->get_data()['phase'],'needs_lead');unlink($f);});
$run('Hugging Face async polling, owner authorization, and failure refunds',function(){update_option('rk_ai_visualizer_settings',array('enabled'=>true,'provider'=>'huggingface','hf_token'=>'test-token','free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24,'ip_per_hour'=>20,'timeout'=>120));$script=array(array('code'=>200,'body'=>json_encode(array('request_id'=>'r1','status_url'=>'https://queue.fal.run/fal-ai/x/status','response_url'=>'https://queue.fal.run/fal-ai/x'))),array('code'=>200,'body'=>json_encode(array('status'=>'IN_PROGRESS'))),array('code'=>200,'body'=>json_encode(array('status'=>'COMPLETED'))),array('code'=>200,'body'=>json_encode(array('images'=>array(array('url'=>'https://cdn.example.test/result.png'))))));$calls=array();$GLOBALS['wp_filters']['rk_ai_visualizer_http']=function($pre,$method,$url,$args)use(&$script,&$calls){$calls[]=array($method,$url,$args);return array_shift($script);};$_COOKIE['rk_ai_viz']=str_repeat('b',32);$f=tempnam(sys_get_temp_dir(),'rkimg');file_put_contents($f,test_png());$e=new Engine();$r=$e->generate('flooring',request_generate($f));$d=$r->get_data();t_eq($d['status'],'pending');$poll=new WP_REST_Request();$poll->params['job']=$d['job'];$_COOKIE['rk_ai_viz']=str_repeat('c',32);t_error($e->status($poll),'rk_viz_no_job','foreign owner');$_COOKIE['rk_ai_viz']=str_repeat('b',32);t_eq($e->status($poll)->get_data()['status'],'pending');$done=$e->status($poll);t_eq($done->get_data()['status'],'success');t_eq($done->get_data()['imageUrl'],'https://cdn.example.test/result.png');t_assert(false===strpos($calls[0][1],'test-token'),'token leaked into URL');unlink($f);unset($GLOBALS['wp_filters']['rk_ai_visualizer_http']);});
$run('remote custom backend status URLs must stay on configured HTTPS host',function(){update_option('rk_ai_visualizer_settings',array('enabled'=>true,'provider'=>'custom','custom_url'=>'https://api.example.test/visualize','custom_key'=>'secret','custom_header'=>'X-Key','free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24,'ip_per_hour'=>10));$GLOBALS['wp_filters']['rk_ai_visualizer_http']=function(){return array('code'=>200,'body'=>json_encode(array('statusUrl'=>'https://evil.example.test/job')));};$_COOKIE['rk_ai_viz']=str_repeat('d',32);$f=tempnam(sys_get_temp_dir(),'rkimg');file_put_contents($f,test_png());$e=new Engine();t_error($e->generate('flooring',request_generate($f)),'rk_viz_provider','unsafe status URL');$state=get_transient('rk_ai_viz_flooring_'.substr(hash('sha256',str_repeat('d',32)),0,32));t_eq($state['used'],0,'provider failure should refund quota');unlink($f);unset($GLOBALS['wp_filters']['rk_ai_visualizer_http']);});
$run('definition lookup, unknown definitions, and response security',function(){ $e=new Engine(); t_assert($e->definition('missing')===null,'unknown definition exists');$r=$e->quota('missing');t_error($r,'rk_viz_definition','unknown definition response');});
$run('upload size cap rejects oversized images before decoding',function()use($definition){$f=tempnam(sys_get_temp_dir(),'rkbig');$h=fopen($f,'wb');ftruncate($h,10485761);fclose($h);$r=new WP_REST_Request();$r->files=array('image'=>array('tmp_name'=>$f,'error'=>0));t_error(Validation::upload($r,$definition),'rk_viz_too_large','oversized image');unlink($f);});
$run('asynchronous provider failure refunds the reserved generation',function(){$cfg=array('enabled'=>true,'provider'=>'huggingface','hf_token'=>'fake-token','free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24,'ip_per_hour'=>10,'timeout'=>120);update_option('rk_ai_visualizer_settings',$cfg);$script=array(array('code'=>200,'body'=>json_encode(array('status_url'=>'https://queue.fal.run/job/status','response_url'=>'https://queue.fal.run/job'))),array('code'=>200,'body'=>json_encode(array('status'=>'FAILED'))));$GLOBALS['wp_filters']['rk_ai_visualizer_http']=function()use(&$script){return array_shift($script);};$_COOKIE['rk_ai_viz']=str_repeat('e',32);$f=tempnam(sys_get_temp_dir(),'rkimg');file_put_contents($f,test_png());$engine=new Engine();$started=$engine->generate('flooring',request_generate($f))->get_data();$key='rk_ai_viz_flooring_'.substr(hash('sha256',str_repeat('e',32)),0,32);t_eq(get_transient($key)['used'],1,'reservation counted while running');$poll=new WP_REST_Request();$poll->params['job']=$started['job'];t_error($engine->status($poll),'rk_viz_provider','failed async job');t_eq(get_transient($key)['used'],0,'failed async job was refunded');unlink($f);unset($GLOBALS['wp_filters']['rk_ai_visualizer_http']);});
$run('REST registration exposes definition-aware and legacy Flooring paths',function(){\RK\AIVisualizer\Rest\Routes::register();$found=array();foreach($GLOBALS['wp_routes'] as $r)$found[]=$r[0].$r[1];foreach(array('rk-ai/v1/visualizer/quota','rk-ai/v1/visualizer/(?P<visualizer>[a-z0-9_-]+)/generate','rk/v1/visualizer/status','rk/v1/visualizer/(?P<visualizer>[a-z0-9_-]+)/lead') as $route)t_assert(in_array($route,$found,true),'route not registered: '.$route);});
echo "\n$tests tests, $failed failures\n"; exit($failed?1:0);
